def as_list(val):
    return [val] if isinstance(val, str) else list(val)

stmts = [
    {'Action': 's3:GetObject'},
    {'Action': ['s3:PutObject', 's3:DeleteObject']},
]
actions = [a for s in stmts for a in as_list(s['Action'])]
print(len(actions), actions[0])

def xor(a, b):
    return bytes(x ^ y for x, y in zip(a, b))

pt = b'HI'
key = b'\x20\x20'
ct = xor(pt, key)
print(ct, xor(ct, key))

import ipaddress, re
text = 'src=192.0.2.5 bad=999.1.1.1 dst=198.51.100.7'
cands = re.findall(r'\b\d{1,3}(?:\.\d{1,3}){3}\b', text)
valid = []
for c in cands:
    try:
        valid.append(str(ipaddress.IPv4Address(c)))
    except ValueError:
        pass
print(len(cands), valid)
